WITH numbered AS (SELECT id,category,row_number() OVER(PARTITION BY category ORDER BY id) AS n FROM public.game_cards WHERE trip_id IS NULL AND game_number=5 AND category IN ('travel','food','childhood','deep')) UPDATE public.game_cards g SET prompt=(CASE numbered.category WHEN 'food' THEN (ARRAY['Which ingredient is commonly used in the cuisine of {destination}?','Name a traditional breakfast in {destination}.','Which non-alcoholic drink is common in {destination}?','Name a local fruit in {destination}.','Which staple grain is used in {destination}?','Name a traditional dessert in {destination}.','What is a common cooking technique in {destination}?','What food is served at celebrations in {destination}?','Name a vegetarian dish in {destination}.','What is a common snack in {city}?','Which spice is often used in {destination}?','What is a traditional market food in {city}?'])[1+(numbered.n-1)%12] WHEN 'childhood' THEN (ARRAY['Name a traditional playground game in {destination}.','What sport is popular among children in {destination}?','What is a common after-school activity in {destination}?','Name a traditional toy from {destination}.','What craft is often taught to children in {destination}?','What is a well-known school custom in {destination}?','Name a family holiday custom in {destination}.','What musical instrument might a child learn in {destination}?','Name a traditional story from {destination}.','What is a popular school lunch in {destination}?','What is a common greeting at school in {destination}?','Name a festival for families in {destination}.'])[1+(numbered.n-1)%12] WHEN 'deep' THEN (ARRAY['Name an art tradition in {destination}.','What etiquette should a visitor know in {destination}?','Name a historical invention from {destination}.','Who is a celebrated athlete from {destination}?','Name an architectural style seen in {city}.','What is a documented turning point in the history of {destination}?','Name a music genre from {destination}.','What is a conservation concern in {destination}?','Name a language spoken in {destination}.','What traditional craft is practiced in {destination}?','What is the meaning of a local symbol in {destination}?','Name a verified fact about a world-famous landmark in {city}.'])[1+(numbered.n-1)%12] ELSE (ARRAY['Which country is {destination} in?','Which continent is {destination} on?','What currency is used in {destination}?','Name a language spoken in {destination}.','What time zone does {city} use?','What is a common greeting in {destination}?','Name a public holiday celebrated in {destination}.','What public transport is common in {city}?','What sport is popular in {destination}?','What is a verified historical fact about {city}?','What is a world-famous landmark in {city}?','What season is it in {destination} right now?'])[1+(numbered.n-1)%12] END) FROM numbered WHERE g.id=numbered.id;